<template>
<div v-pre>
  <dialog id="ikasExcelImportDialog" class="certification-modal"><form id="ikasExcelImportForm" class="risk-register-form"><div class="section-heading compact"><div><p class="eyebrow">IMPORT EXCEL IKAS</p><h3>Pilih domain yang diperbarui</h3><p class="muted">Isian, pertanyaan, dan rubrik hanya diperbarui pada domain yang dipilih. Domain lain tetap tersimpan.</p></div></div><div id="ikasExcelImportDomains" class="permission-checks"></div><p id="ikasExcelImportStatus" role="status" aria-live="polite"></p><div class="csf-form-actions"><button type="submit" class="button button-accent">Import domain terpilih</button><button type="button" class="button button-quiet" id="ikasExcelImportCancel">Batal</button></div></form></dialog>
  <section id="ikasView" class="view">
    <div class="page-heading"><div><p class="eyebrow">BSSN / IKAS v1.2.1</p><h2>IKAS BSSN</h2><p class="lede">Instrumen Penilaian Kematangan Keamanan Siber</p></div><button class="button button-quiet" type="button" data-ikas-reset>Reset assessment</button></div>
    <div class="risk-management-tabs"><button class="button button-accent" type="button" data-ikas-tab="overview">Overview</button><button class="button button-quiet" type="button" data-ikas-tab="core">Assessment Core</button><button class="button button-quiet" type="button" data-ikas-tab="respondent">Data Responden</button><button class="button button-quiet" type="button" data-ikas-tab="gaps">Gaps</button></div>
    <p id="ikasStatus" role="status" aria-live="polite"></p>
    <div data-ikas-panel="overview"><div class="hero-grid"><article class="score-panel"><div class="panel-kicker">Indeks Nilai Kematangan</div><div class="score-line"><strong id="ikasOverallScore">—</strong><span>/ 5.0</span></div><p id="ikasOverallLevel">Belum dinilai</p><div class="meter"><span id="ikasOverallMeter"></span></div><div class="score-foot"><span>0 Awal</span><span>5 Inovatif</span></div></article><article class="stat-panel"><span class="stat-label">Completion</span><strong id="ikasCompletionValue">0%</strong><span class="stat-detail" id="ikasCompletion"></span><div class="mini-ring"></div></article><article class="stat-panel"><span class="stat-label">Priority gaps</span><strong id="ikasPriorityGap">0</strong><span class="stat-detail">Kontrol di bawah target kematangan</span><div class="gap-bars"><i></i><i></i><i></i><i></i><i></i></div></article></div><div class="section-heading"><div><p class="eyebrow">FRAMEWORK COVERAGE</p><h3>Domain IKAS BSSN</h3></div><span class="target-chip">Skala indeks <b>0–5</b></span></div><div class="function-cards" id="ikasDomainCards"></div><div class="section-heading"><div><p class="eyebrow">IKAS SUMMARY</p><h3>Kematangan per kategori</h3></div></div><div class="excel-wrap summary-wrap"><table class="excel-table summary-table"><thead><tr><th>Domain</th><th>Kategori</th><th>Target</th><th>Indeks Nilai Kematangan</th><th>Gap target</th></tr></thead><tbody id="ikasSummaryBody"></tbody></table></div><div class="section-heading radar-heading"><div><p class="eyebrow">MATURITY PROFILE</p><h3>Target dan Indeks Nilai Kematangan</h3></div></div><article class="radar-panel"><div class="radar-chart-wrap"><canvas id="ikasRadar" width="700" height="360" style="max-width:100%;width:100%;height:360px" aria-label="Radar nilai IKAS per domain"></canvas></div><div class="radar-legend"><span class="radar-series active"><i class="legend-practice"></i>Indeks Nilai Kematangan</span><span class="radar-series active"><i class="legend-target"></i>Target</span></div></article><div data-gap-summary="ikas"></div></div>
    <div data-ikas-panel="core" hidden><div class="page-heading"><div><p class="eyebrow">IKAS BSSN FRAMEWORK</p><h2>IKAS BSSN Core</h2><p class="lede">Domain, kategori, pertanyaan, Indeks Nilai Kematangan, dan Keterangan Validasi.</p></div></div><div class="toolbar"><label class="search-box"><input id="ikasCoreSearch" type="search" placeholder="Cari ID, pertanyaan, rubrik, ruang lingkup..." aria-label="Cari assessment IKAS"></label><select id="ikasCoreDomain" aria-label="Domain IKAS"><option value="all">Semua domain</option></select><select id="ikasCoreStatus" aria-label="Status assessment"><option value="all">Semua kontrol</option><option value="unscored">Belum dinilai</option><option value="scored">Sudah dinilai</option><option value="gaps">Di bawah target</option></select></div><p id="ikasCoreCount"></p><div id="ikasCoreList"></div><div id="ikasCorePagination" class="list-pagination"></div></div>
    <div data-ikas-panel="respondent" hidden><form id="ikasRespondentForm" class="risk-register-form ikas-form-panel"><div class="ikas-panel-heading"><p class="eyebrow">PROFIL ASSESSMENT</p><h3>Data Responden</h3><p class="muted">Lengkapi identitas organisasi, sistem elektronik, dan penanggung jawab penilaian.</p></div><div id="ikasRespondentFields" class="csf-form-grid ikas-respondent-grid"></div><div class="csf-form-actions"><button type="submit" class="button button-accent">Simpan responden</button></div></form></div>
    <div data-ikas-panel="gaps" data-gap-tab="ikas" hidden></div>
    <div class="assessment-year-actions"><button type="button" class="button button-quiet" data-ikas-excel>Export Excel IKAS</button><button type="button" class="button button-quiet" data-ikas-import-excel>Import Excel IKAS</button><input id="ikasExcelImport" type="file" accept=".xlsx" hidden><button type="button" class="button button-quiet" data-view="ikas-manage">Manage IKAS BSSN</button></div>
  </section>
  <section id="ikasAssessmentView" class="view"><div class="page-heading"><div><p class="eyebrow">IKAS BSSN / ASSESSMENT</p><h2 id="ikasAssessmentTitle">Assessment IKAS</h2><p id="ikasFunctionProgress"></p></div><button type="button" class="button button-quiet" data-view="ikas">Kembali ke IKAS</button></div><div class="toolbar"><label class="search-box"><input id="ikasAssessmentSearch" type="search" placeholder="Cari pertanyaan..." aria-label="Cari pertanyaan IKAS"></label><select id="ikasAssessmentStatus" aria-label="Filter penilaian"><option value="all">Semua kontrol</option><option value="unscored">Belum dinilai</option><option value="scored">Sudah dinilai</option><option value="gaps">Di bawah target</option></select></div><div id="ikasControlList"></div><div id="ikasAssessmentPagination" class="list-pagination"></div></section>
  <section id="ikasManageView" class="view"><div class="page-heading"><div><p class="eyebrow">IKAS BSSN / MANAGE</p><h2>Manage IKAS BSSN</h2><p class="lede">Kelola domain, kategori, pertanyaan, ruang lingkup, serta rubrik indeks 0–5.</p></div><button id="ikasNewButton" type="button" class="button button-accent">+ New control</button></div><div class="toolbar"><label class="search-box"><input id="ikasManageSearch" type="search" placeholder="Cari kontrol..." aria-label="Cari kontrol IKAS"></label><select id="ikasManageDomain" aria-label="Filter domain IKAS"><option value="all">Semua domain</option></select></div><p id="ikasManageStatus" role="status"></p><div class="excel-wrap"><table class="excel-table"><thead><tr><th>ID</th><th>Domain</th><th>Kategori</th><th>Subkategori</th><th>Pertanyaan</th><th>Ruang lingkup</th><th>Applicability</th><th>Aksi</th></tr></thead><tbody id="ikasManageBody"></tbody></table></div><div id="ikasManagePagination" class="list-pagination"></div></section>
  <dialog id="ikasControlModal" class="ikas-control-dialog"><form id="ikasControlForm" class="csf-form-grid ikas-manage-form"><h2>Kontrol IKAS BSSN</h2><input name="originalId" type="hidden"><label>ID kontrol<input name="id" required maxlength="200"></label><label>Domain<select name="function" required></select></label><label>Kategori<input name="category" required></label><label>Nomor subkategori<input name="subcategoryId" required pattern="\d+\.\d+\.\d+" placeholder="1.1.1"></label><label>Judul subkategori<textarea name="subcategoryTitle" required></textarea></label><label>Pertanyaan<textarea name="subcategory" required rows="4"></textarea></label><label>Ruang lingkup<input name="scope" required></label><label>Applicability<select name="applicability"><option>Applicable</option><option>Not applicable</option></select></label><label>Alasan / catatan kontrol<textarea name="notes" rows="3"></textarea></label><div id="ikasRubricFields"></div><label>Referensi<textarea name="references" rows="2"></textarea></label><label>Minimum evidence<textarea name="minimumEvidence" rows="2"></textarea></label><p role="status" aria-live="polite"></p><div class="assessment-year-actions"><button type="submit" class="button button-accent">Simpan kontrol</button><button type="button" class="button button-quiet" data-ikas-modal-cancel>Batal</button></div></form></dialog>
</div>
</template>
<style>
.ikas-control-row { display:block; padding:24px; margin-bottom:18px; border:1px solid var(--line); border-radius:12px; overflow-wrap:anywhere; background:var(--white,#fff); box-shadow:var(--shadow) }
.ikas-assessment-fields { display:grid; grid-template-columns:minmax(240px,.8fr) minmax(0,1.2fr); gap:24px; margin:24px 0; padding:22px; background:var(--paper,#f1f5f9); border:1px solid var(--line); border-radius:12px }
.ikas-assessment-fields label,.ikas-respondent-field { display:flex; flex-direction:column; gap:9px; min-width:0; font-size:12px; font-weight:600; color:var(--ink) }
.ikas-index-field small { margin-top:6px; color:var(--muted); font-weight:400; line-height:1.7; white-space:pre-wrap }
.ikas-description-field textarea { min-height:160px; resize:vertical }
.ikas-control-heading h3 { margin:12px 0; font-size:17px; line-height:1.6; color:var(--ink) }
.ikas-control-heading p { margin:8px 0; line-height:1.7 }
.ikas-scope { display:inline-flex; padding:6px 10px; border-radius:7px; background:var(--lime); color:var(--green); font-size:11px }
.ikas-control-footer { display:flex; justify-content:space-between; gap:16px; margin-top:20px; padding-top:16px; border-top:1px solid var(--line); color:var(--muted) }
.ikas-form-panel { padding:28px; margin:22px 0; border:1px solid var(--line); border-radius:14px; background:var(--white,#fff); box-shadow:var(--shadow) }
.ikas-panel-heading { margin-bottom:24px; padding-bottom:18px; border-bottom:1px solid var(--line) }
.ikas-panel-heading h3 { margin:8px 0; font-size:20px; color:var(--ink) }
.ikas-panel-heading p { margin:6px 0 }
.ikas-respondent-grid { display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); gap:22px 24px }
.ikas-respondent-field small { color:var(--muted); font-size:11px; font-weight:400 }
.ikas-respondent-field.ikas-field-wide { grid-column:span 2 }
body.workspace-ui :is(#ikasView,#ikasAssessmentView,#ikasManageView,#ikasControlModal) :is(input:not([type=file]):not([type=hidden]):not([type=checkbox]):not([type=radio]),select,textarea) { display:block; width:100%; min-width:0; min-height:42px; padding:10px 12px; border:1px solid #d8e3f1; border-radius:9px; background:var(--white,#fff); color:var(--ink); font:inherit; font-size:13px; box-sizing:border-box; transition:border-color .18s,box-shadow .18s }
body.workspace-ui :is(#ikasView,#ikasAssessmentView,#ikasManageView,#ikasControlModal) :is(input,select,textarea):focus { outline:none; border-color:#80aaf0; box-shadow:0 0 0 3px #326fe014 }
body.workspace-ui :is(#ikasView,#ikasAssessmentView,#ikasManageView) .toolbar { align-items:center; flex-wrap:wrap; gap:12px; padding:14px; border-radius:12px; border:1px solid var(--line); background:var(--white,#fff) }
body.workspace-ui :is(#ikasView,#ikasAssessmentView,#ikasManageView) .toolbar > select { flex:0 1 290px; width:auto }
body.workspace-ui :is(#ikasView,#ikasAssessmentView,#ikasManageView) .search-box { min-width:220px; padding:0 12px }
body.workspace-ui :is(#ikasView,#ikasAssessmentView,#ikasManageView) .search-box input { border:0; box-shadow:none; padding-inline:0; background:transparent }
body.workspace-ui :is(#ikasView,#ikasAssessmentView,#ikasManageView) .search-box :is(#ikasCoreSearch,#ikasAssessmentSearch,#ikasManageSearch) { border:0; box-shadow:none; padding-inline:0; background:transparent }
body.workspace-ui :is(#ikasView,#ikasAssessmentView,#ikasManageView) .search-box:focus-within { border-color:#80aaf0; box-shadow:0 0 0 3px #326fe014 }
#ikasDomainCards { grid-template-columns:repeat(4,minmax(0,1fr)); margin:22px 0; gap:16px }
.ikas-domain-card { display:flex; flex-direction:column; gap:14px; padding:22px; border-radius:14px; border:1px solid var(--line); box-shadow:var(--shadow) }
.ikas-domain-card h3 { margin:0; font-size:14px; font-weight:700; line-height:1.6; color:var(--ink) }
.ikas-domain-card .button { margin-top:auto; align-self:flex-start }
.ikas-domain-score { display:flex; align-items:baseline; gap:6px; color:var(--muted) }
.ikas-domain-score strong { font-size:30px; font-weight:700; color:var(--ink) }
.ikas-domain-card .ikas-level { color:var(--muted); font-size:11px }
.ikas-domain-top { display:flex; justify-content:space-between; align-items:center; gap:12px }
.ikas-domain-icon { display:grid; place-items:center; width:42px; height:42px; border-radius:11px; background:var(--lime); color:var(--green); border:1px solid var(--line) }
.ikas-domain-icon svg { width:23px; height:23px }
.ikas-domain-weight { padding:5px 8px; border:1px solid var(--line); border-radius:7px; color:var(--muted); font-size:10px; font-weight:600; white-space:nowrap }
.ikas-overview-summary { padding:24px; border:1px solid var(--line); border-radius:14px; background:var(--white,#fff); margin-top:24px; box-shadow:var(--shadow) }
.ikas-overview-summary .section-heading { margin-top:0 }
.ikas-overview-summary #ikasOverallScore { font-size:32px; color:var(--ink) }
html[data-theme=dark] .ikas-overview-summary { background:#19273d; border-color:#35455c }
.ikas-manage-form { display:block }
.ikas-form-panel .csf-form-actions { display:flex; margin-top:26px; padding-top:20px; border-top:1px solid var(--line) }
body.workspace-ui :is(#ikasView,#ikasAssessmentView,#ikasManageView) .assessment-year-toolbar label { white-space:nowrap }
body.workspace-ui :is(#ikasView,#ikasAssessmentView,#ikasManageView) .assessment-year-toolbar select { width:auto; min-width:105px }
html[data-theme=dark] :is(.ikas-form-panel,.ikas-domain-card) { background:#19273d; border-color:#35455c }
html[data-theme=dark] .ikas-assessment-fields { background:#152035; border-color:#35455c }
html[data-theme=dark] body.workspace-ui :is(#ikasView,#ikasAssessmentView,#ikasManageView,#ikasControlModal) :is(input,select,textarea) { background:#1e2c43; border-color:#40516c; color:#e2e8f0 }
@media(max-width:1200px){#ikasDomainCards{grid-template-columns:repeat(2,minmax(0,1fr))}.ikas-respondent-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media(max-width:700px){#ikasDomainCards,.ikas-respondent-grid,.ikas-assessment-fields{grid-template-columns:minmax(0,1fr)}.ikas-respondent-field.ikas-field-wide{grid-column:auto}.ikas-form-panel{padding:20px}.ikas-assessment-fields{padding:16px}.ikas-control-footer{flex-direction:column}body.workspace-ui :is(#ikasView,#ikasAssessmentView,#ikasManageView) .toolbar>select{flex:1 1 100%;width:100%}}
.ikas-control-row details { margin:12px 0; padding:12px; background:var(--surface); border:1px solid var(--line); border-radius:8px }
#ikasControlModal { width:min(600px,94vw); max-height:85vh; overflow:auto; padding:24px; border:1px solid var(--line); border-radius:16px; background:var(--surface,#fff); color:var(--navy) }
#ikasControlModal::backdrop { background:#14243888 }
#ikasControlModal label { display:grid; gap:7px; margin:16px 0 }
#ikasControlModal :is(input,select,textarea) { padding:10px; border:1px solid var(--line); border-radius:8px; background:var(--surface,#fff); color:inherit }
#ikasControlModal textarea,#ikasControlModal input,#ikasControlModal select { box-sizing:border-box; width:100%; min-width:0 }
#ikasSummaryBody input { width:80px }
.ikas-core-table { min-width:2000px }
.ikas-core-table th,.ikas-core-table td { vertical-align:top; min-width:120px }
.ikas-core-table td:nth-child(3),.ikas-core-table td:nth-child(4),.ikas-core-table td:nth-child(7),.ikas-core-table td:nth-child(8) { min-width:260px; max-width:380px; white-space:normal }
.ikas-core-table textarea { min-height:180px; resize:vertical }
.ikas-core-table details p { white-space:pre-wrap; line-height:1.7 }
#ikasExcelImportDomains .permission-option small { display:block; margin-top:5px; color:var(--muted) }
@media(max-width:700px){.ikas-score-columns{grid-template-columns:1fr}.ikas-control-row{padding:16px}.ikas-control-row .attachment-actions{flex-wrap:wrap}}
</style>
